def compute_order_totals(orders, tax_rate=0.08, discount_threshold=1000.0):
    processed = []
    for o in orders:
        discount = 0.10 if o["price"] >= discount_threshold else 0.0
        effective_price = o["price"] * (1 - discount)
        tax = effective_price * tax_rate
        final_total = round(effective_price + tax, 2)
        processed.append({**o, "total": final_total, "discount": discount})
    return processed

