class CSVParser:
    def __init__(self, lines):
        self.lines = lines

    def parse(self):
        records = []
        for line in self.lines:
            parts = line.strip().split(',')
            if len(parts) != 3:
                print('Bad row:', line)
                continue
            try:
                records.append({
                    'id': parts[0],
                    'name': parts[1],
                    'score': int(parts[2])
                })
            except ValueError:
                print('Bad row:', line)
        return records

def main():
    data = [
        'id,name,score\n',
        '1,Alice,92\n',
        '2,Bob,85\n',
        '3,Carol,invalid\n'
    ]
    parser = CSVParser(data)
    print(parser.parse())

if __name__ == '__main__':
    main()

