import logging

logging.basicConfig(level='INFO')

class UserRepository:
    def __init__(self, users):
        self.users = {u['id']: u for u in users}

    def find(self, user_id):
        return self.users.get(user_id)

class OrderRepository:
    def __init__(self):
        self.orders = []

    def add(self, order):
        self.orders.append(order)
        return order

class AuthService:
    def __init__(self, repo):
        self.repo = repo

    def authenticate(self, user_id, password):
        user = self.repo.find(user_id)
        if user and user['password'] == password:
            logging.info('Authenticated user %s', user_id)
            return True
        return False

class OrderService:
    def __init__(self, auth, order_repo):
        self.auth = auth
        self.order_repo = order_repo

    def place_order(self, user_id, items):
        if not self.auth.authenticate(user_id, 'temp'):
            return 'Unauthorized'
        order = {'id': len(self.order_repo.orders) + 1, 'user': user_id, 'items': items}
        self.order_repo.add(order)
        logging.info('Order %s placed', order['id'])
        return 'Order placed'

