from abc import ABC, abstractmethod

class ReportPluginMeta(type):
    def __new__(mcls, name, bases, namespace):
        cls = super().__new__(mcls, name, bases, namespace)
        if hasattr(cls, 'plugin_name'):
            ReportPluginRegistry.register(cls.plugin_name, cls)
        return cls

class ReportPluginRegistry:
    _plugins = {}

    @classmethod
    def register(cls, name, plugin_class):
        cls._plugins[name] = plugin_class

    @classmethod
    def create(cls, name):
        if name not in cls._plugins:
            raise ValueError('Unknown plugin: ' + name)
        return cls._plugins[name]()

class ReportPlugin(ABC, metaclass=ReportPluginMeta):
    @abstractmethod
    def generate(self):
        pass

class PDFReport(ReportPlugin):
    plugin_name = 'pdf'
    def generate(self):
        return 'PDF content'

class CSVReport(ReportPlugin):
    plugin_name = 'csv'
    def generate(self):
        return 'CSV content'

if __name__ == '__main__':
    print(ReportPluginRegistry.create('pdf').generate())
    print(ReportPluginRegistry.create('csv').generate())
